import{_ as t,a as r,b as i}from"./chunks/e0f84668a6d637eb37b0.Bh8-Xm1c.js";import{_ as o,C as l,o as n,c as s,j as e,a as h,E as m,a6 as u}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"价值创造：建立我一人企业的核心技能","description":"","frontmatter":{"title":"价值创造：建立我一人企业的核心技能","originalTitle":"Value Creation: The Skill That Built My One-Person Business","date":"2023-04-01","originalUrl":"https://thedankoe.com/letters/value-creation-the-skill-that-built-my-one-person-business/","minutes":12,"sourceHash":"4018b914f31ee32b15a72d1c5cc0ce236cd7b3caa93d2524c27f03bd6a0fe876","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/value-creation-the-skill-that-built-my-one-person-business/"}]]},"headers":[],"relativePath":"letters/value-creation-the-skill-that-built-my-one-person-business.md","filePath":"letters/value-creation-the-skill-that-built-my-one-person-business.md"}'),c={name:"letters/value-creation-the-skill-that-built-my-one-person-business.md"};function d(b,p,f,g,_,k){const a=l("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"价值创造-建立我一人企业的核心技能",tabindex:"-1"},[h("价值创造：建立我一人企业的核心技能 "),e("a",{class:"header-anchor",href:"#价值创造-建立我一人企业的核心技能","aria-label":'Permalink to "价值创造：建立我一人企业的核心技能"'},"​")],-1)),m(a),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/iAYVVLHm5Oc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我最喜欢的失败创业经历之一，是用 Photoshop 创作数字艺术。</p><p>这是我最喜欢的作品之一（如果你把我的 Instagram 一直滑到最底下，就能找到所有的作品）。</p><p><img src="'+t+'" alt=""></p><p>这一尝试让我第一次意识到了社交媒体的力量。</p><p>我效仿那些大账号增长粉丝的方式，具体做法如下：</p><ul><li>标记分享数字艺术的社区页面</li><li>尽可能创作出最好的合成图像，以便它们能被分享</li><li>对摄影师的图像进行重新混搭（二创），希望他们能分享我的内容（就像在 Twitter 帖子中提及大账号，好让他们转发给自己的受众一样）</li></ul><p>那几乎是 5 年前的事了，我也是这样在 Instagram 上获得了最初的 2,500 名粉丝。</p><p>在把自己锁在房间里 3 个月、废寝忘食、全身心投入创作之后，我放弃了。</p><p>我热爱创作，但完全不知道该如何变现。</p><p>我的艺术是有价值的，但还没价值到能让人掏钱的地步。</p><p>在我的脑海里，这甚至根本不是一种可能性。</p><p>我意识到，作为一名艺术家，我无法维持自己的生活方式。</p><p>我觉得我必须学习一门更有利可图的技能去做自由职业。</p><p>当然，那时候我就是个白痴。</p><p>如果我当时懂我现在懂的这些，我可能仍然在用 Photoshop 搞创作。</p><p>我现在更喜欢写作多一点，所以我不打算重返数字艺术领域了，但如果我能回到过去，我会这样做：</p><ul><li>继续增长，并意识到我的受众就是流量来源</li><li>创建产品或服务，将这些流量导向那里（在当时的情况下就是课程和辅导）</li><li>学习文案、营销和报价创建，从而在市场上定位我的产品</li><li>与个人发展领域的创作者合作，将他们最好的想法可视化，并成为该领域的权威</li></ul><p>换句话说，我会去做我们在一人企业视频中谈论过的所有事情。</p><p>就像我所有失败的生意一样，它们都给我上了宝贵的一课。</p><p>这些技能，比如 Photoshop，都对我当前品牌的成功做出了贡献（比如，我所有的设计和缩略图都是我自己做的）。</p><p>但有一项技能，我认为这些年来我 95% 的品牌、销售和受众增长都归功于它。</p><h2 id="人类心理学的普遍模式" tabindex="-1">人类心理学的普遍模式 <a class="header-anchor" href="#人类心理学的普遍模式" aria-label="Permalink to &quot;人类心理学的普遍模式&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>人们让你去学的每一项“赚钱”技能，都与普遍模式和人类心理学息息相关。</p><p>如果不是，那它们就不赚钱。</p><p>如果它们不赚钱，那你就需要叠加那些能让它们赚钱的技能。</p><p>在所有人类行为（包括人们掏出信用卡付钱给你）的底层，是这三样东西：</p><p><strong>1) 生存</strong> —— 复制你基因和意识中信息的欲望，无论生理还是心理。</p><p><strong>2) 进化</strong> —— 通过创造来超越毁灭的欲望。</p><p><strong>3) 蜕变</strong> —— 追求更高质量体验的欲望。</p><p>它们都非常相似，在这封信接下来的内容中，你可以把它们看作是同义词。</p><p>你也可以通过观察讲故事、游戏、音乐和建筑来剖析这些模式。它们各自的原则都可以用来增强你技能栈的综合影响力。</p><p>用我能想到的最简单的方式来解释，所有这些都使用了同一个框架：目的（purpose）、路径（path）、优先级（priority）。</p><h3 id="_1-目的" tabindex="-1">1) 目的 <a class="header-anchor" href="#_1-目的" aria-label="Permalink to &quot;1) 目的&quot;">​</a></h3><p>行为的改变始于一个问题，并照亮一个为了克服该问题而设定的目标。</p><p>目标 = 目的。</p><p>目的 = 欲望。</p><p>欲望 = 问题是如何产生的。</p><p>就像故事通过说明或暗示一个问题来开启好奇心循环一样。</p><p>或者像落地页瞄准你生活中的一个相关问题来激励你采取行动。</p><p>又或者像你受够了生活中的某个问题，最终决定去解决它。</p><p>通过照亮某人生活中的某个问题，你创造了目的。</p><h3 id="_2-路径" tabindex="-1">2) 路径 <a class="header-anchor" href="#_2-路径" aria-label="Permalink to &quot;2) 路径&quot;">​</a></h3><p>当一个问题被识别出来，伴随的目标展现出一个潜在的未来时，清晰度就是那座桥梁。</p><p>清晰的反义词是混乱，我们可不想让客户一想到使用我们的产品就感到焦虑和不知所措。</p><h3 id="_3-优先级" tabindex="-1">3) 优先级 <a class="header-anchor" href="#_3-优先级" aria-label="Permalink to &quot;3) 优先级&quot;">​</a></h3><p>为了让这个问题进入某个人的意识，它必须对他们来说很重要。</p><p>如果这个问题对他们不重要，你就无法抓住他们的注意力来给他们指明路径。那时路径甚至都无关紧要了，因为它既帮不到他们，他们也没有去行动的动力。</p><p>重要性是主观的。</p><p>人类是通过其身份认同的视角来感知问题的。</p><p>如果你试图把一款自我提升产品卖给一个超重的游戏玩家，你必须以一种非常具体的方式来定位那个产品。</p><p>顺便说一句，你也可以使用相同的框架来重新掌控你的生活。</p><h2 id="价值创造框架" tabindex="-1">价值创造框架 <a class="header-anchor" href="#价值创造框架" aria-label="Permalink to &quot;价值创造框架&quot;">​</a></h2><p>目的 &gt; 路径 &gt; 优先级的框架很好，但让我们把它变得更实用些。</p><p>在下一节中，我们将讨论我们在哪里可以使用这些东西。</p><p>把下面的所有部分都当作“营销火力”，你可以在你的内容、促销，甚至日常生活的语言中使用它们，来阐明你的产品或你自身的价值。</p><p>这些就是点石成金的步骤。</p><p>这些步骤，一旦应用到我的任何尝试中，就让我的企业赚到了 100 万美元。</p><p>这些就是练习最核心技能——<em>价值创造</em>——的步骤。</p><p>如果你还没有一个产品报价，可以在<a href="https://thedankoe.com/the-best-online-business-model-to-make-1-million-in-2023/" target="_blank" rel="noreferrer">这里学习如何创建一个</a>，或者在<a href="https://thedankoe.com/you-have-100000-of-knowledge-trapped-in-your-brain/" target="_blank" rel="noreferrer">这里学习如何打包你脑海中的知识</a>。</p><p>随着时间的推移，这些会变得越来越容易。</p><p>如果你在填写所有这些内容时感到吃力，不用担心。</p><h3 id="_1-认知层级" tabindex="-1">1) 认知层级 <a class="header-anchor" href="#_1-认知层级" aria-label="Permalink to &quot;1) 认知层级&quot;">​</a></h3><p>你在线上和线下遇到的每一个人，对他们自身的问题以及你的价值（产品、服务或你的存在），都处在某个认知（或意识）层级上。</p><p>请注意，这些与心理学 / 哲学中的<a href="https://thedankoe.com/a-message-from-a-recovering-atheist-how-to-find-god/" target="_blank" rel="noreferrer">自我发展阶段</a>或螺旋动力学量表有重叠。</p><p><strong>第 1 层：无意识（Unaware）</strong></p><p>如果你想写出病毒式传播的推文，或者制作爆款的 YouTube 视频，就要围绕“无意识”阶段来构建你的内容。</p><p>在这个阶段，人们既没有意识到自己的问题，也不知道你的报价。</p><p>你需要通过文字和语言，让他们意识到自己的问题，以及这个问题正在如何影响他们的生活。</p><p>就他们面临的问题，去教育、告知并与你的读者产生共鸣。</p><p>如果你想帮助某人变得健康，你可以指出，缺乏适当的营养是他们昏昏沉沉的根源。</p><p>我会写这样一条推文：</p><p><em>“你总是感到疲惫，因为你往嘴里狂塞速食烤饼、外卖，以及会导致营养不良的食物。”</em></p><p>是有点刻薄，对，但这正是我的风格。</p><p><strong>第 2 层：问题意识（Problem Aware）</strong></p><p>你的读者意识到了问题，但可能并不了解它，或者不知道有解决办法。</p><p>我会写这样一篇帖子：</p><p><em>“如果你总是感到疲惫：</em></p><p><em>– 每天早上称体重</em></p><p><em>– 吃够与你体重相当的蛋白质</em></p><p><em>– 喝水直到尿液清澈</em></p><p><em>– 每天走 10,000 步</em></p><p><em>等你感觉好到一想到吃垃圾食品破坏这种感觉就反感时，再来感谢我。”</em></p><p>在长篇内容中，你可以既教育人们认识他们面临的问题，又提供一个解决方案。</p><p>而对于短篇形式，如推文或短视频，为了达到最大效果，你通常要针对 1-3 层。不要搞得太深奥或太自作聪明。</p><p><strong>第 3 层：方案意识（Solution Aware）</strong></p><p>在这个阶段，人们意识到了自己的问题，也知道有解决方案的存在。但他们不知道<em>你的</em>解决方案的存在。</p><p>现在，你要给出清晰的解决方案或鼓励他们采取行动。</p><p><strong>第 4 层：产品意识（Product Aware）</strong></p><p>人们意识到了你的解决方案和其他类似的解决方案。</p><p>你的工作是陈述为什么你的产品更好。</p><p>强调利益的文案是关键。</p><p>这是一个我会写的帖子：</p><p><em>“为什么你应该开始间歇性禁食：</em></p><p><em>– 早晨的专注力极其变态</em></p><p><em>– 你不需要去安排早饭</em></p><p><em>– 午饭和晚饭可以吃得极其丰盛”</em></p><p>我可以把这篇帖子写完，但你懂我的意思，而且文章已经开始变长了。</p><p><strong>第 5 层：充分意识（Most Aware）</strong></p><p>人们对你的解决方案一清二楚，只需要临门一脚的推动。</p><p>你可以继续推广你的产品，直到时机成熟（就像重定向广告，人们通常不会在第一次看到你的产品时就购买）……</p><p>或者你可以提供限时折扣，或实施其他稀缺性策略。但要谨慎使用这一招。</p><h3 id="_2-定位-positioning" tabindex="-1">2) 定位（Positioning） <a class="header-anchor" href="#_2-定位-positioning" aria-label="Permalink to &quot;2) 定位（Positioning）&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>既然我们了解了认知层级，就可以开始设计有说服力的信息了。</p><p>顺便说一句，我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>中提供了 Notion 模板，并深度教学了如何将你大脑里的知识打包并卖出产品。</p><p>我们之前曾多次讨论过永恒市场（健康、财富、人际关系），但这次我们要探讨得更深。</p><p>人类有 8 种无法忽视的欲望。</p><p>你的所有内容、销售页面或写作，都应该从这些欲望的视角去写：</p><ul><li>生存</li><li>生活享受</li><li>免于恐惧的自由</li><li>性伴侣</li><li>舒适与清晰</li><li>感知地位</li><li>社区安全感</li><li>社会认同</li></ul><p>教育人们认识阻碍这些欲望实现的问题，并提供克服它们的解决方案。</p><p>注意每个人的“细分领域”都是自我实现。</p><p>我的商业哲学就是：</p><p>解决你自己的问题 &gt; 记录下解决方案 &gt; 改善他人以提升集体意识，这依然成立。</p><h3 id="_3-核心问题-big-problem" tabindex="-1">3) 核心问题（Big Problem） <a class="header-anchor" href="#_3-核心问题-big-problem" aria-label="Permalink to &quot;3) 核心问题（Big Problem）&quot;">​</a></h3><p>从你选择用来定位的特定认知层级和角度出发，你要找出一个核心问题，以此作为你写作、演讲或创作的开端。</p><p>从“无意识”阶段和“感知地位”的角度，我可以找出这样一个核心问题，比如：</p><p>找不到一份 6 位数薪水的工作。</p><p>接着我可以放大这个问题，并阐述没有一份 6 位数薪水的工作是如何影响他们的约会、支付账单的能力，以及这个世界是如何本能地缺乏对他们的尊重。</p><p>你也能看出来从“生存”等其他角度出发，这个问题会有怎样的打击感。</p><p>很肤浅？</p><p>是的。</p><p>欢迎来到人类生活。</p><p>深度来自于你解决了自己（以及他人）生活中的肤浅问题之后。</p><p>如果占据一个人全部心思的问题是支付账单或者性爱，那没人会关心什么正念或存在主义。</p><p>我们必须在不同的发展阶段去提升人们。</p><h3 id="_4-独特机制-unique-mechanism" tabindex="-1">4) 独特机制（Unique Mechanism） <a class="header-anchor" href="#_4-独特机制-unique-mechanism" aria-label="Permalink to &quot;4) 独特机制（Unique Mechanism）&quot;">​</a></h3><p>你需要一个在所有人中脱颖而出的解决方案。</p><p>再次强调，这就是为什么我建议你“自己去弄清楚”，因为你可以通过实验创造出一个独特的解决方案。</p><p>就像 Greg O&#39;Gallagher 将间歇性禁食和倒金字塔训练法结合起来，打造了一套适合他特定生活方式的健身计划。</p><p>然后，他针对自己生活方式中的问题，将它们与人类的 8 种欲望相对应，卖出了自己独特的解决方案。</p><p>想想<em>你</em>会如何一步步解决这个问题，然后给这些步骤安上一个引人注目的名字。</p><p>我的<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时内容生态系统（2-Hour Content Ecosystem）</a>就是一个例子。</p><h3 id="_5-扫射式利益点-bullet-spray-benefits" tabindex="-1">5) 扫射式利益点（Bullet Spray Benefits） <a class="header-anchor" href="#_5-扫射式利益点-bullet-spray-benefits" aria-label="Permalink to &quot;5) 扫射式利益点（Bullet Spray Benefits）&quot;">​</a></h3><p>在我的文案和推文中，我喜欢用海量的好处把人淹没。</p><p>当你用项目符号列出你独特解决方案中那些直击要害的好处时，你就给了人们<em>多个</em>购买（或互动）的理由。</p><p>即使其中一点没有引起共鸣，另一点也可能成为他们转化的原因。</p><h3 id="_6-证据" tabindex="-1">6) 证据 <a class="header-anchor" href="#_6-证据" aria-label="Permalink to &quot;6) 证据&quot;">​</a></h3><p>个人成果、客户评价以及你能收集到的任何其他统计数据或事实，都将帮助人们相信你能交付成果。</p><p>不要低估个人经历的力量。这是我们很少见到的东西。人们渴望人与人之间的连接。</p><p>这就是为什么我90%的通讯和视频都以讲述我遇到的问题的个人经历作为开头。</p><p>当然，客户评价非常有力量，在刚开始时，你应该把获取客户评价当成你的全职工作，但你不能等到有了这些评价才开始销售。</p><h3 id="_7-大创意" tabindex="-1">7) 大创意 <a class="header-anchor" href="#_7-大创意" aria-label="Permalink to &quot;7) 大创意&quot;">​</a></h3><p>在你充实了其他价值创造要点之后，你需要反复琢磨它们，从而提炼出大创意。</p><p>大创意在某种程度上是一句能说明你价值的总结。</p><p>大多数广为流传的名言都是大创意。</p><p>那些留在你脑海中的内容就是大创意。</p><p>主动寻找大创意并将其内化为你自己的东西，是发现大创意的最好方法。</p><p>比特币是未来的数字货币。</p><p>Uber是现代的出租车服务。</p><p>ChatGPT真他**的是一切。</p><p>它可以与你列出的任何要点重叠，或者<em>就是</em>其中之一，只要它足够有力。</p><p>我花了一段时间才搞明白这一点，而且我现在依然无法清晰地表达它。</p><p>通过实践和挣扎去理解它吧。</p><p>或者，你可以用<a href="https://thedankoe.com/how-i-read-books-for-maximum-intelligence-5-minute-habit/" target="_blank" rel="noreferrer">上周的信</a>来寻找大创意。</p><h3 id="_8-风险逆转与最终结果" tabindex="-1">8) 风险逆转与最终结果 <a class="header-anchor" href="#_8-风险逆转与最终结果" aria-label="Permalink to &quot;8) 风险逆转与最终结果&quot;">​</a></h3><p>在你起步初期，一个令人信服的风险逆转策略将帮助你达成交易。</p><p>大多数人会选择退款保证，这很酷，但你可以通过将其与明确的最终结果相结合，让它变得更诱人。</p><p>销售约会产品时的例子：</p><p>“如果你没能在60天内获得5次约会，我们将退还你的投资。”</p><p>谁会不买呢？</p><p>并且这也迫使你必须交付结果。</p><p>你必须在风险逆转中添加附加条件，并声明他们必须按照你提供的所有内容采取行动。</p><h2 id="营销乐高" tabindex="-1">营销乐高 <a class="header-anchor" href="#营销乐高" aria-label="Permalink to &quot;营销乐高&quot;">​</a></h2><p>把你所写、所说，或者与他人互动的任何事情中，把上面的所有内容都当成你的“营销乐高”。</p><p>任何事情。</p><p>如果你想变强，你就必须抓住每一个可能的时刻来练习这个。</p><p>仅仅阅读这篇文章是不够的。</p><p>阅读任何东西都是不够的。</p><p>你必须启动一个项目，遇到<em>现实世界的问题</em>，让现实来教你那些阅读无法教给你的东西。</p><p>有成千上万个微小的细微差别，没有任何人能够在一篇内容、一本书或一门课程中为你阐明。</p><p>你必须通过行动，有意识和无意识地去掌握它们。</p><p>这里有几个你可以开始练习价值创造的地方：</p><h3 id="社交媒体推文" tabindex="-1">社交媒体推文 <a class="header-anchor" href="#社交媒体推文" aria-label="Permalink to &quot;社交媒体推文&quot;">​</a></h3><p>吸引人的长篇内容遵循以下格式：</p><ul><li>引入一个问题并放大它的痛点</li><li>提供背景信息，或者将他们提升到意识到解决方案的层次（通常通过证据或故事）</li><li>给出克服该问题的可执行步骤（最好将该方法命名为你自己的独创）</li><li>融入实施该系统的好处，从而促使人们行动</li><li>使用你内容的大创意作为标题或大标题</li></ul><p>我经常谈论的一人企业（One Person Business），对于生活中的许多大问题来说，既是一个经过验证的大创意，也是一个独特的机制。</p><p>长篇内容可以带领人们走过所有认知层次。</p><p>为了互动，瞄准第1-3级。</p><p>为了销售，瞄准第2-5级。</p><p>为了硬广促销，瞄准第3-5级。</p><p>这适用于通讯、连推（threads）、轮播图、配文和YouTube视频。</p><p>短篇内容一次仅限使用一个层级。</p><p>你可以把你的任何“营销乐高”变成一篇帖子。</p><p>这适用于推文、单一的IG帖子、TikToks 和 Shorts 短视频等。</p><h3 id="落地页和销售页" tabindex="-1">落地页和销售页 <a class="header-anchor" href="#落地页和销售页" aria-label="Permalink to &quot;落地页和销售页&quot;">​</a></h3><p>与撰写长篇内容类似，落地页和销售页也遵循同样的模式。</p><p>如果你想用文案框架进行练习，请使用：</p><ul><li><strong>PASTOR</strong> – problem（问题）、amplify（放大）、story（故事）、testimony（证明）、offer（报价）、response（回应）</li><li><strong>AIDA</strong> – attention（注意力）、interest（兴趣）、desire（欲望）、action（行动）</li><li><strong>PAS</strong> – problem（问题）、amplify（放大）、solution（解决方案）</li></ul><p>并随着时间的推移不断精进。</p><p>对于你的大标题和副标题，你要尝试把大部分（如果不是全部的话）“营销乐高”都塞进去。</p><p>这也适用于销售电话、私信或演示演讲。</p><h3 id="课程大纲" tabindex="-1">课程大纲 <a class="header-anchor" href="#课程大纲" aria-label="Permalink to &quot;课程大纲&quot;">​</a></h3><p>你希望人们根据你所教的内容采取行动。</p><p>你不能在他们购买了你的产品后就停止运用说服力。</p><p>你必须保持他们的注意力，给他们清晰的指引，并鼓励他们去行动。</p><p>不然他们怎么能获得结果？</p><p>如果他们没拿到结果，你怎么获得客户评价呢？</p><h3 id="日常对话" tabindex="-1">日常对话 <a class="header-anchor" href="#日常对话" aria-label="Permalink to &quot;日常对话&quot;">​</a></h3><p>所有的人类交流都带有说服性。</p><p>当你和某人交谈时，你会试图从一个共同的视角出发。</p><p>当你不这么做时，争论就开始了。</p><p>一个视角往往包含一个共同的目标，所以用一个问题来开启对话，以抓住他们的注意力。</p><p>你：“兄弟，我最近觉得好累，什么活儿都干不进去。”</p><p>他们：“一样啊哥们，我总是觉得累。”</p><p>你：“是啊，上次我有这种感觉的时候，我开始深入健身，我打算恢复我的训练计划了。”</p><p>他们：“什么训练计划？”</p><p>你：“我采用了垂直饮食法（vertical diet），在健身房做兄弟分化训练（bro split）。”</p><p>对话会继续下去，希望借此能让他们了解你在做什么，并给他们提供一些有用且值得尝试的东西（以及这样做的诸多好处）。</p><p>那场对话是很有价值的（并且可以转化成内容 😉)</p><p>就是这样。</p><p>走出去，开始在你做的每一件事中练习。</p><p>你的表达能力、现金流和生活质量都将直线飙升。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/value-creation-the-skill-that-built-my-one-person-business">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',217))])}const y=o(c,[["render",d]]);export{x as __pageData,y as default};
